 function resumirPasta(pasta, nome) {
   const sessoes = fs.readdirSync(pasta)
     .filter((f) => /^ses_.+\.json$/.test(f))
     .map((f) => {
       const analise = analisar(JSON.parse(fs.readFileSync(path.join(pasta, f), 'utf8')));
